    // Freeze the listener list for this pass. An unsubscribe during the loop
    // mutates a *fresh* copy (via ensureCanMutateNextListeners), so nobody in
    // this pass gets skipped; a subscribe during the loop lands on the fresh
    // copy and is only called from the next pass onwards.
    const listeners = (currentListeners = nextListeners)
    for (let i = 0; i < listeners.length; i++) {
      listeners[i]!()
    }
  }

  /* ----- base dispatch (the innermost link of the chain) ------------- */
  function baseDispatch(action: any): any {
    if (action === null || typeof action !== 'object') {
      throw new TypeError(
        'Actions must be plain objects. Use custom middleware for async actions.',
      )
    }
    // The reducer-dispatch guard: while the reducer runs, no dispatch may start.
    if (isDispatching) {
      throw new Error('Reducers may not dispatch actions.')
    }
    isDispatching = true
    try {
      state = reducer(state, action)
    } finally {
      isDispatching = false
    }

    if (viewIndex === null) {
      // Recording is live: capture every action + resulting state.
      history.push({ action, state })
    }
    needsNotify = true
    return action
  }

  /* ----- public dispatch (with notification batching) ---------------- */
  function dispatch(action: any): any {
    // Fail fast even before middleware run — e.g. a reducer calling dispatch
    // through the store reference must throw immediately.
    if (isDispatching) {
      throw new Error('Reducers may not dispatch actions.')
    }
    dispatchDepth++
    try {
      return composedDispatch(action)
    } finally {
      dispatchDepth--
      // Only the outermost dispatch notifies, and it notifies exactly once.
      if (dispatchDepth === 0 && needsNotify) {
        needsNotify = false
        flushNotifications()
      }
    }
  }

  /* ----- getState / subscribe ---------------------------------------- */
  function getState(): S {
    if (isDispatching) {
      throw new Error(
        'You may not call store.getState() while the reducer is executing.',
      )
    }
    return viewIndex === null ? state : history[viewIndex]!.state
  }

  function subscribe(listener: () => void): () => void {
    if (typeof listener !== 'function') {
      throw new TypeError('Expected the listener to be a function.')
    }
    let subscribed = true
    ensureCanMutateNextListeners()
    nextListeners.push(listener)

    return function unsubscribe() {
      if (!subscribed) return
      subscribed = false
      ensureCanMutateNextListeners()
      const index = nextListeners.indexOf(listener)
      if (index >= 0) nextListeners.splice(index, 1)
    }
  }

  /* ----- wire up middleware (right-to-left like applyMiddleware) ------ */
  const middlewareAPI: MiddlewareAPI<S> = {
    getState,
    // Deliberately routes through the wrapped `dispatch`, so middleware can
    // dispatch nested actions that go through the whole chain again.
    dispatch: (action: any) => dispatch(action),
  }

  const composedDispatch = compose(
    ...middlewares.map((mw) => mw(middlewareAPI)),
  )(baseDispatch)

  /* ----- devtools ----------------------------------------------------- */
  function jumpTo(index: number): void {
    if (!Number.isInteger(index) || index < 0 || index >= history.length) {
      throw new RangeError(
        `jumpTo(index): index ${index} is out of bounds for history of length ${history.length}.`,
      )
    }
    viewIndex = index // pausing recording happens implicitly: we only record when viewIndex === null
  }

  function resume(): void {
    viewIndex = null
  }

  const devtools: Devtools<S, A> = {
    size: () => history.length,
    getHistory: () => history.slice(),
    jumpTo,
    resume,
    isPaused: () => viewIndex !== null,
    currentIndex: () => viewIndex,
  }

  return {
    getState,
    dispatch,
    subscribe,
    jumpTo,
    resume,
    devtools,
  }
}
