    expect(history).toHaveLength(3)
    expect(history.map((e) => e.state)).toEqual([1, 3, 6])
    expect(history.map((e) => e.action.type)).toEqual(['ADD', 'ADD', 'MULT'])
    expect(store.devtools.size()).toBe(3)
  })

  it('jumpTo rewinds getState to a historical state and pauses recording; resume returns to the present', () => {
    const store = createStore(counter, 0)
    store.dispatch(add(1)) // 1
    store.dispatch(add(2)) // 3
    store.dispatch(add(4)) // 7

    // Rewind to the state after the FIRST action.
    store.jumpTo(0)
    expect(store.devtools.isPaused()).toBe(true)
    expect(store.getState()).toBe(1)

