  })
})

describe('reducer-dispatch guard', () => {
  function makeEvilStore() {
    let store!: ReturnType<typeof createStore<Counter>>
    const evil: Reducer<Counter> = (state = 0, action) => {
      if (action.type === 'EVIL') {
        // A reducer trying to dispatch — must throw.
        store.dispatch({ type: 'SHOULDN_NOT_HAPPEN' })
      }
      return counter(state, action)
    }
    store = createStore(evil, 0)
    return store
  }

  it('throws synchronously when a reducer dispatches', () => {
    const store = makeEvilStore()
    expect(() => store.dispatch({ type: 'EVIL' })).toThrow(
      /Reducers may not dispatch actions/,
    )
  })

  it('leaves the store intact after the guard fires', () => {
    const store = makeEvilStore()
    expect(() => store.dispatch({ type: 'EVIL' })).toThrow()

    expect(store.getState()).toBe(0) // no partial/corrupted update
    store.dispatch(add(41)) // still fully usable
    expect(store.getState()).toBe(41)
    const spy = vi.fn()
    store.subscribe(spy)
    store.dispatch(add(1))
    expect(spy).toHaveBeenCalledTimes(1)
  })

  it('getState inside a reducer throws too', () => {
    let boom!: () => void
    const nosy: Reducer<Counter> = (state = 0, action) => {
      if (action.type === 'NOSEY') boom()
      return counter(state, action)
    }
    const store = createStore(nosy, 0)
    expect(() => store.dispatch({ type: 'NOSEY' })).toThrow(
      /while the reducer is executing/,
    )
    void boom
  })
})

