  it('composes right-to-left', () => {
    const trace: string[] = []
    const f =
      (tag: string) =>
      (next: any) =>
      (...args: any[]) => {
        trace.push(`${tag}>`)
        const r = next(...args)
        trace.push(`<${tag}`)
        return r
      }
    const chained = compose(f('a'), f('b'), f('c'))((x: number) => x * 2)
    expect(chained(3)).toBe(6)
    expect(trace).toEqual(['a>', 'b>', 'c>', '<c', '<b', '<a'])
  })

  it('handles zero and one middlewares', () => {
    expect(compose()(add(1))).toEqual(add(1))
    let called = false
    compose((next: any) => (a: any) => {
      called = true
      return next(a)
    })((x: any) => x)(add(2))
    expect(called).toBe(true)
  })
})
